'use strict';
/* Explicit panel caps only. No Telegram request, queue resume or counter reset. */
window.OperationBudgets=(()=>{
 const base='/api/scanner/operations',states=new Map(),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let accounts=[];
 const key=a=>a&&typeof a.id==='string'&&Number.isSafeInteger(a.telegram_id)&&a.telegram_id>0?a.id+':'+a.telegram_id:'',current=(id,tid)=>accounts.find(a=>a.id===id&&a.telegram_id===tid&&a.connection==='connected');
 const state=a=>{const k=key(a);if(!states.has(k))states.set(k,{busy:false,error:'',note:'',budget:null,limit:50,reason:'',confirmed:false,pending:null});return states.get(k);};
 const accountFrom=el=>{const box=el.closest('[data-operation-budgets]');return box&&current(box.dataset.budgetAccount,Number(box.dataset.budgetTelegramId));};
 function valid(b,a){return b&&b.account===a.id&&b.telegram_id===a.telegram_id&&/^\d{4}-\d{2}-\d{2}$/.test(b.utc_day)&&b.scope==='panel_internal_utc_day'&&b.editable===(a.id!=='primary')&&['job_baseline_daily_limit','effective_daily_limit','account_count_today','remaining_today'].every(k=>Number.isSafeInteger(b[k])&&b[k]>=0)&&b.effective_daily_limit>=1&&b.effective_daily_limit<=100&&(!b.override||b.override.account===a.id&&b.override.telegram_id===a.telegram_id&&b.override.utc_day===b.utc_day&&b.override.daily_limit===b.effective_daily_limit&&typeof b.override.reason==='string'&&typeof b.override.request_key==='string');}
 async function api(a,body){const r=await fetch(base+'/accounts/'+encodeURIComponent(a.id)+'/daily-budget',{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Scanner-Request':'1'},signal:AbortSignal.timeout(60000),...(body?{body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw Error('Сервер не подтвердил результат. Повторная проверка использует тот же ключ.');}if(!r.ok){const e=Error(typeof d?.detail==='string'?d.detail:'Не удалось изменить предел.');e.rejected=r.status>=400&&r.status<500;throw e;}return d;}
 function content(a){const s=state(a),b=s.budget,locked=s.busy||!!s.pending;return `<h4>Дневной предел панели</h4><p class="small">Внутренний предел исходящих попыток, общий для заданий этого аккаунта за день UTC. Ограничения Telegram проверяются отдельно. Сохранение не запускает задания и не обнуляет историю.</p><button type="button" class="button secondary" data-budget-action="load"${s.busy?' disabled':''}>${b?'Обновить дневной счётчик':'Показать дневной счётчик'}</button>${b?`<p class="small" role="status">День UTC: ${h(b.utc_day)}. Использовано: ${b.account_count_today}. Действующий предел панели: ${b.effective_daily_limit}. Осталось: ${b.remaining_today}.</p><p class="small">Предел по сохранённым заданиям: ${b.job_baseline_daily_limit}. ${b.override?'Отдельно подтверждённый предел на сегодня: '+b.effective_daily_limit+'. Причина: '+h(b.override.reason):'Отдельный предел на сегодня не задан.'} В каждом задании также действует его собственный сохранённый предел.</p>${b.editable?`<form data-budget-form><fieldset style="border:0;padding:0;min-width:0"${locked?' disabled':''}><label class="ls-field">Предел панели для этого аккаунта на ${h(b.utc_day)} UTC<input type="number" name="daily_limit" min="1" max="100" required value="${h(s.limit)}"></label><label class="ls-field">Причина изменения<textarea name="reason" rows="2" minlength="8" maxlength="500" required>${h(s.reason)}</textarea></label><label><input type="checkbox" name="confirmed" required${s.confirmed?' checked':''}> Подтверждаю изменение предела только для этого аккаунта и дня UTC</label></fieldset><p><button class="button"${s.busy?' disabled':''}>${s.pending?'Проверить сохранение того же предела':'Сохранить предел на сегодня'}</button></p></form>`:'<p class="small">Предел основного аккаунта здесь доступен только для просмотра.</p>'}`:''}${s.pending?'<p class="notice">Подтверждение сохранения ещё не получено. Повтор использует тот же ключ и параметры.</p>':''}<p class="${s.error?'ls-error':'small'}" role="status" aria-live="polite">${h(s.error||s.note)}</p>`;}
 function accountView(a){return a.connection==='connected'&&key(a)?`<details data-operation-budgets data-budget-account="${h(a.id)}" data-budget-telegram-id="${a.telegram_id}" style="min-width:0;overflow-wrap:anywhere"><summary>Дневной предел и счётчик</summary><div data-budget-content>${content(a)}</div></details>`:'';}
 function render(a){for(const el of document.querySelectorAll('[data-operation-budgets]'))if(el.dataset.budgetAccount===a.id&&Number(el.dataset.budgetTelegramId)===a.telegram_id){const box=el.querySelector('[data-budget-content]');if(box)box.innerHTML=content(a);}}
 function mount(next){accounts=next||[];const active=new Set(accounts.filter(a=>a.connection==='connected').map(key));for(const k of states.keys())if(!active.has(k))states.delete(k);for(const a of accounts)if(a.connection==='connected'&&key(a))render(a);}
 function read(f,a){const s=state(a);if(s.pending||s.busy)return;s.limit=Number(f.elements.daily_limit.value);s.reason=f.elements.reason.value;s.confirmed=f.elements.confirmed.checked;}
 async function load(a){const s=state(a);if(s.busy)return;s.busy=true;s.error='';render(a);try{const b=await api(a);if(!current(a.id,a.telegram_id)||states.get(key(a))!==s)return;if(!valid(b,a))throw Error('Счётчик относится к другому аккаунту или неполон. Обновите список.');s.budget=b;if(s.pending&&b.override?.request_key===s.pending.request_key){s.pending=null;s.confirmed=false;s.note='Предел сохранён. Задания не запускались.';}else s.note='Счётчик обновлён.';}catch(e){s.error=e.message;}finally{s.busy=false;if(current(a.id,a.telegram_id)&&states.get(key(a))===s)render(a);}}
 async function save(a){const s=state(a);if(s.busy||!s.budget||a.id==='primary')return;if(!s.pending){if(!s.confirmed||!Number.isSafeInteger(s.limit)||s.limit<1||s.limit>100||s.reason.trim().length<8||s.reason.trim().length>500){s.error='Укажите предел от 1 до 100, причину от 8 символов и подтверждение.';render(a);return;}s.pending={confirmed:true,telegram_id:a.telegram_id,utc_day:s.budget.utc_day,daily_limit:s.limit,reason:s.reason.trim(),request_key:crypto.randomUUID()};}const payload=s.pending;s.busy=true;s.error='';render(a);try{const r=await api(a,payload);if(!current(a.id,a.telegram_id)||states.get(key(a))!==s)return;if(!valid(r.budget,a)||!r.receipt||r.receipt.account!==a.id||Object.entries(payload).some(([k,v])=>r.receipt[k]!==v))throw Error('Сервер не подтвердил сохранённый предел. Проверьте тот же запрос.');s.pending=null;s.confirmed=false;s.budget=r.budget;s.note='Предел сохранён. История и состояние заданий сохранены.';}catch(e){if(e.rejected)s.pending=null;s.error=e.message;}finally{s.busy=false;if(current(a.id,a.telegram_id)&&states.get(key(a))===s)render(a);}}
 for(const type of ['input','change'])document.addEventListener(type,e=>{const f=e.target.closest('[data-budget-form]'),a=f&&accountFrom(f);if(a)read(f,a);});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-budget-action]'),a=b&&accountFrom(b);if(a&&!b.disabled&&b.dataset.budgetAction==='load')void load(a);});
 document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('[data-budget-form]'))return;e.preventDefault();e.stopImmediatePropagation();const a=accountFrom(f);if(a){read(f,a);void save(a);}},true);
 return {accountView,mount};
})();
